#!/usr/bin/env node
// boundary-invoice-fmt@2.1.0 compatible CLI: CSV -> bif/2 invoices JSON
const { readFileSync, writeFileSync, mkdirSync } = require("node:fs");
const { dirname } = require("node:path");
const { createHash } = require("node:crypto");

const [,, input, output] = process.argv;
if (!input || !output) { console.error("usage: cli.js <orders.csv> <out.json>"); process.exit(1); }

const lines = readFileSync(input, "utf8").trim().split(/\r?\n/);
const rows = lines.slice(1);
const invoices = rows.map((line) => {
  const [id, customer, amount] = line.split(",");
  const net_cents = Math.round(parseFloat(amount) * 100);
  const tax_cents = Math.round(net_cents * 0.21);
  return {
    invoice: "INV-" + String(id.trim()).padStart(6, "0"),
    customer: customer.trim(),
    net_cents,
    tax_cents,
  };
});
const digest = createHash("sha256").update(JSON.stringify(invoices)).digest("hex").slice(0, 16);
const out = { format: "bif/2", invoices, digest };
mkdirSync(dirname(output), { recursive: true });
writeFileSync(output, JSON.stringify(out, null, 2) + "\n");
console.log("wrote " + output);

